import { Button } from '@absoluteui/components/button';

const el = document.querySelector<HTMLButtonElement>('#save');
if (el) {
  const save = Button.enhance(el, { variant: 'primary' });
  el.addEventListener('click', () => {
    save.setLoading(true);
  });
}

import { Button } from '@absoluteui/components/button';

const search = Button.create({ icon: 'search', label: 'Search', variant: 'ghost' });
document.body.append(search.element);

import { configureAbsoluteUI } from '@absoluteui/core';
import { Button } from '@absoluteui/components/button';

configureAbsoluteUI({ common: { density: 'compact' }, components: { button: { size: 'sm' } } });
const b = Button.create({ text: 'Apply' });
document.body.append(b.element);
